-- Development-only grants. Production signing and adapter accounts require explicit role assignment.
insert into RHN_SYS_ROLE_PERM_ASSIGN (ID_ROLE_PERM_ASSIGN, ID_TNT, ID_ACC_ROLE, ID_ACC_PERM, DT_VALID_FROM, DT_VALID_TO, ID_USER_GRANTED, DT_CREATED)
select p.ID_ACC_PERM + 1000000000000000, p.ID_TNT, r.ID_ACC_ROLE, p.ID_ACC_PERM, current_timestamp, null, 362387869790222, current_timestamp
from RHN_SYS_ACC_PERM p join RHN_SYS_ACC_ROLE r on r.ID_TNT=p.ID_TNT and r.CD_ACC_ROLE='PORTAL_OPERATOR'
where p.ID_TNT=362387869790209 and p.CD_ACC_PERM like 'DIAGNOSTICS.%' and p.CD_ACC_PERM <> 'DIAGNOSTICS.ACCESS'
 and not exists (select 1 from RHN_SYS_ROLE_PERM_ASSIGN a where a.ID_TNT=p.ID_TNT and a.ID_ACC_ROLE=r.ID_ACC_ROLE and a.ID_ACC_PERM=p.ID_ACC_PERM);

